/**
 * Secret references of nao_config.yaml, in the syntax the CLI supports:
 *
 *     {{ env('NAME') }}    ${{ env('NAME') }}    {{ aws('secret/field') }}    {{ k8s('ns/secret/field') }}
 *
 * The CLI substitutes them in the raw text before parsing the YAML, so a reference does not have
 * to be quoted. nao mirrors that here by replacing each one with a placeholder rather than its
 * value, so an unquoted reference survives parsing without letting a secret alter the document.
 */

const SECRET_PATTERN = /\$?\{\{\s*(env|aws|k8s)\(\s*['"]([^'"]+)['"]\s*\)\s*\}\}/g;

const PLACEHOLDER_PATTERN = /__nao_secret_(\d+)__/g;

export type SecretProtocol = 'env' | 'aws' | 'k8s';

export type SecretReference = { protocol: SecretProtocol; identifier: string };

export type MaskedConfig = { content: string; references: SecretReference[] };

/** Resolves the placeholders of a masked config back to a usable value, or null. */
export type SecretResolver = (value: unknown) => string | null;

export function maskSecretReferences(content: string): MaskedConfig {
	const references: SecretReference[] = [];

	const masked = content.replace(SECRET_PATTERN, (_match, protocol: SecretProtocol, identifier: string) => {
		references.push({ protocol, identifier });
		return `__nao_secret_${references.length - 1}__`;
	});

	return { content: masked, references };
}

/**
 * Resolve `env` placeholders from the project env vars then the process env.
 *
 * `aws` and `k8s` are resolved by the CLI only, so a value that still needs them resolves to null
 * and the caller falls back to the environment.
 */
export function createSecretResolver(references: SecretReference[], extraEnv: Record<string, string>): SecretResolver {
	return (value) => {
		if (typeof value !== 'string') {
			return null;
		}

		let resolvable = true;
		const resolved = value.replace(PLACEHOLDER_PATTERN, (_match, index: string) => {
			const reference = references[Number(index)];
			if (reference?.protocol !== 'env') {
				resolvable = false;
				return '';
			}
			return extraEnv[reference.identifier] || process.env[reference.identifier] || '';
		});

		return resolvable && resolved.trim() ? resolved : null;
	};
}

export function listEnvReferences(content: string): string[] {
	const names = maskSecretReferences(content)
		.references.filter((reference) => reference.protocol === 'env')
		.map((reference) => reference.identifier);

	return [...new Set(names)];
}

