type LlmBlock = { llm: unknown; references: SecretReference[] };

const rawCache = new Map<string, { mtimeMs: number; block: LlmBlock }>();

/** Parse the config file, caching by modification time so hot paths only pay a stat. */
function loadLlmBlock(projectPath: string): LlmBlock {
	const filePath = configPath(projectPath);

	let mtimeMs: number;
	try {
		mtimeMs = fs.statSync(filePath).mtimeMs;
	} catch {
		rawCache.delete(filePath);
		return { llm: null, references: [] };
	}

	const cached = rawCache.get(filePath);
	if (cached?.mtimeMs === mtimeMs) {
		return cached.block;
	}

	const block: LlmBlock = { llm: null, references: [] };
	try {
		const masked = maskSecretReferences(fs.readFileSync(filePath, 'utf-8'));
		const config = yaml.load(masked.content);
		block.llm = isRecord(config) ? (config.llm ?? null) : null;
		block.references = masked.references;
	} catch (err) {
		logger.warn(`Failed to parse ${filePath}: ${err instanceof Error ? err.message : String(err)}`, {
			source: 'system',
		});
	}

	rawCache.set(filePath, { mtimeMs, block });
	return block;
}

